// Test inputs and independent expectations from the accepted original game.
// No expected results are generated by the current CraftingSession.
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {readCraftingFixture} from './compile-crafting-content.mjs';
const output=process.argv[2];
assert(output&&!fs.existsSync(output));
const policy=readCraftingFixture('policy'),actions=readCraftingFixture('actions');
const row=actions.rows.find(r=>r.name==='salvage-break');
const natural=row.before.bag[0];
const helmet=(uid,x)=>({...natural,uid,x,y:1,baseId:'helmet_armor',rarity:'common',name:'Workshop test helmet',implicitRolls:[],affixes:[]});
const input={board:{w:8,h:8},items:[helmet(1,0),helmet(2,3),natural,{...natural,uid:38,x:1},{...natural,uid:39,x:2,affixes:natural.affixes.map(a=>({...a,locked:true}))}],
  equipped:{},overflow:[],essences:row.before.wallet,account:{craftLore:row.before.lore,ledger:{},features:[],progression:true}};
const expected={salvageWallet:row.after.wallet,salvageLore:row.after.lore,ledger:row.after.saved[0].ledger,
  craftCost:policy.content.costs.find(r=>r.rank===1).cost,socketCost:policy.content.craft.socketCost,
  rerollCost:policy.content.oracleCosts.magic,affixId:natural.affixes[0].id};
fs.writeFileSync(output,JSON.stringify({input,expected})+'\n');
